#!/usr/bin/env python3
"""Adapt a repository created from the Big-3 template.

Run from the repository root. With no flag, runs every local step in order
(each one asks before changing anything):

  --clean       delete the template's generated files (Scorecard results,
                badge JSON, committed SAST reports, CHANGELOG.md)
  --rename      replace the template's owner/repo and OWNER/REPO placeholders
                with the repository behind `git remote get-url origin`
  --version     write the current version to .release-please-manifest.json
  --contact     fill the Code of Conduct enforcement contact
  --sonar       fill the SonarQube Cloud organisation and project keys
  --signing     set up SSH commit signing for this clone only (git config --local)

GitHub side (needs `gh auth login` as a repo admin):

  --gh-vars     prompt for each Actions secret and variable the workflows use
  --governance  run scripts/apply-governance.sh (ruleset + repo settings)
  --workflow    check that everything above is configured; exits 1 on errors

Common options: --yes accepts every default without asking, --dry-run only
prints what would change. Standard library only; needs Python 3.9+.
"""

from __future__ import annotations

import argparse
import getpass
import json
import os
import re
import shutil
import subprocess
import sys
from pathlib import Path

TEMPLATE_SLUG = "Julian52575/Big-3-Governed-Template"
PLACEHOLDER_SLUG = "OWNER/REPO"
CONTACT_PLACEHOLDER = "[INSERT CONTACT METHOD]"
SONAR_PLACEHOLDERS = {
    "sonar.organization": "REPLACE_WITH_ORGANIZATION_KEY",
    "sonar.projectKey": "REPLACE_WITH_PROJECT_KEY",
}

# Generated by workflows; a new repository must not show the template's results.
TEMPLATE_FILES = [
    "CHANGELOG.md",
    ".sast/openssf/SCORECARD.md",
    ".readme-badges/scorecard-results.json",
    ".readme-badges/scorecard-badge.json",
]
SAST_REPORT_DIR = ".sast/report"

# (name, kind, required, help). `kind` is "secret" or "variable".
GH_SETTINGS = [
    ("RELEASE_PLEASE_GITHUB_TOKEN", "secret", True,
     "Fine-grained PAT or GitHub App token on this repo with Contents and Pull "
     "requests read/write. release-please.yml fails without it."),
    ("SONARQUBE_TOKEN", "secret", False,
     "SonarQube Cloud analysis token (My Account -> Security). Turns on the "
     "SonarQube job in ci-sast.yml."),
    ("SAST_REPORT_TOKEN", "secret", False,
     "Fine-grained PAT with Contents read/write. Lets ci-sast.yml commit "
     "reports to main; needs a ruleset bypass if main is protected."),
    ("DISCORD_WEBHOOK_URL", "secret", False,
     "Discord channel webhook URL (Channel settings -> Integrations -> "
     "Webhooks). Turns on notify-discord-review-requested.yml."),
    ("MAKE_PR_DRAFT", "variable", False,
     "Set to `true` to have make-pr-draft.yml turn new PRs into drafts."),
]

SEMVER = re.compile(r"^\d+\.\d+\.\d+(-[0-9A-Za-z.-]+)?$")


class Ui:
    def __init__(self, yes: bool, dry_run: bool):
        self.yes = yes
        self.dry_run = dry_run

    def ask(self, prompt: str, default: str = "") -> str:
        if self.yes:
            return default
        suffix = f" [{default}]" if default else ""
        answer = input(f"{prompt}{suffix}: ").strip()
        return answer or default

    def confirm(self, prompt: str, default: bool = True) -> bool:
        if self.yes:
            return default
        hint = "Y/n" if default else "y/N"
        answer = input(f"{prompt} [{hint}] ").strip().lower()
        return default if not answer else answer.startswith("y")


def heading(text: str) -> None:
    print(f"\n== {text}")


def run(cmd: list[str], check: bool = True, input_text: str | None = None) -> subprocess.CompletedProcess:
    return subprocess.run(cmd, check=check, text=True, capture_output=True, input=input_text)


def git(*args: str) -> str:
    return run(["git", *args]).stdout.strip()


def origin_slug() -> str | None:
    """owner/repo from the origin URL (SSH or HTTPS)."""
    try:
        url = git("remote", "get-url", "origin")
    except subprocess.CalledProcessError:
        return None
    m = re.search(r"github\.com[:/]([^/]+)/(.+?)(?:\.git)?/?$", url)
    if not m:
        return None
    slug = f"{m.group(1)}/{m.group(2)}"
    # A renamed repository keeps redirecting from its old URL; ask GitHub for the current name.
    if shutil.which("gh"):
        r = run(["gh", "repo", "view", slug, "--json", "nameWithOwner", "--jq", ".nameWithOwner"], check=False)
        if r.returncode == 0 and r.stdout.strip():
            return r.stdout.strip()
    return slug


def tracked_text_files() -> list[Path]:
    files = []
    for name in git("ls-files").splitlines():
        path = Path(name)
        # README-ADAPT.md documents the placeholders themselves
        if path.name in ("adapt.py", "README-ADAPT.md", "package-lock.json") or not path.is_file():
            continue
        try:
            path.read_text(encoding="utf-8")
        except (UnicodeDecodeError, OSError):
            continue
        files.append(path)
    return files


def replace_in_files(ui: Ui, replacements: dict[str, str]) -> int:
    changed = 0
    for path in tracked_text_files():
        text = path.read_text(encoding="utf-8")
        new = text
        for old, value in replacements.items():
            new = new.replace(old, value)
        if new != text:
            changed += 1
            print(f"  {'would update' if ui.dry_run else 'updated'} {path}")
            if not ui.dry_run:
                path.write_text(new, encoding="utf-8")
    return changed


# --- local steps --------------------------------------------------------------

def step_clean(ui: Ui) -> None:
    heading("Remove the template's generated files")
    targets = [Path(p) for p in TEMPLATE_FILES if Path(p).exists()]
    report = Path(SAST_REPORT_DIR)
    if report.is_dir():
        targets += [p for p in report.iterdir() if p.name != ".gitkeep"]
    if not targets:
        print("  nothing to remove")
        return
    for p in targets:
        print(f"  {p}")
    if not ui.confirm("Delete these?"):
        return
    if ui.dry_run:
        print("  would remove them")
        return
    for p in targets:
        shutil.rmtree(p) if p.is_dir() else p.unlink()
    print("  removed; the workflows regenerate them for this repository")


def step_rename(ui: Ui) -> None:
    heading("Point owner/repo references at this repository")
    detected = origin_slug()
    slug = ui.ask("owner/repo of this repository", detected or "")
    if not re.fullmatch(r"[\w.-]+/[\w.-]+", slug):
        print("  skipped: no valid owner/repo (set the origin remote, or type it)")
        return
    if slug == TEMPLATE_SLUG:
        print("  skipped: origin is the template itself")
        return
    repo = slug.split("/")[1]
    count = replace_in_files(ui, {
        TEMPLATE_SLUG: slug,
        TEMPLATE_SLUG.replace("/", "%2F"): slug.replace("/", "%2F"),
        PLACEHOLDER_SLUG: slug,
        '"package-name": "REPO"': f'"package-name": "{repo}"',
    })
    print(f"  {count} file(s) {'would change' if ui.dry_run else 'changed'}")


def step_version(ui: Ui) -> None:
    heading("Current version (.release-please-manifest.json)")
    path = Path(".release-please-manifest.json")
    current = json.loads(path.read_text()).get(".", "0.0.0") if path.exists() else "0.0.0"
    version = ui.ask("Current version of the project; release-please bumps from it", current)
    if not SEMVER.match(version):
        print(f"  skipped: '{version}' is not a semantic version like 1.4.0")
        return
    print(f"  {'would set' if ui.dry_run else 'set'} version {version}")
    if not ui.dry_run:
        path.write_text(json.dumps({".": version}) + "\n")


def step_contact(ui: Ui) -> None:
    heading("Code of Conduct enforcement contact")
    path = Path("CODE_OF_CONDUCT.md")
    if not path.exists() or CONTACT_PLACEHOLDER not in path.read_text():
        print("  already set")
        return
    contact = ui.ask("Where to report conduct issues (e.g. an email address); blank skips")
    if contact:
        replace_in_files(ui, {CONTACT_PLACEHOLDER: contact})


def step_sonar(ui: Ui) -> None:
    heading("SonarQube Cloud keys (.sast/sonar-project.properties)")
    path = Path(".sast/sonar-project.properties")
    text = path.read_text()
    if not any(v in text for v in SONAR_PLACEHOLDERS.values()):
        print("  already set")
        return
    print("  Only needed with the SONARQUBE_TOKEN secret; see .sast/README.md.")
    for key, placeholder in SONAR_PLACEHOLDERS.items():
        value = ui.ask(f"  {key} (blank skips)")
        if value:
            text = text.replace(f"{key}={placeholder}", f"{key}={value}")
    if not ui.dry_run:
        path.write_text(text)


def step_signing(ui: Ui) -> None:
    heading("Commit signing for this clone (git config --local)")
    if ui.yes:
        print("  skipped with --yes: picking a key is personal; run --signing")
        return
    current = run(["git", "config", "--local", "--get", "user.signingkey"], check=False).stdout.strip()
    if current:
        print(f"  already set: user.signingkey={current}")
        if not ui.confirm("Change it?", default=False):
            return
    keys = sorted(Path.home().glob(".ssh/*.pub"))
    for i, k in enumerate(keys, 1):
        print(f"  {i}. {k}")
    choice = ui.ask("Pick a key number, a path to a .pub file, or `new` to generate one",
                    "1" if keys else "new")
    if choice == "new":
        key = Path.home() / ".ssh" / "id_ed25519_signing"
        email = git("config", "user.email") or "signing"
        print(f"  generating {key}")
        if not ui.dry_run:
            subprocess.run(["ssh-keygen", "-t", "ed25519", "-C", email, "-f", str(key)], check=True)
        pub = Path(f"{key}.pub")
    elif choice.isdigit() and 1 <= int(choice) <= len(keys):
        pub = keys[int(choice) - 1]
    else:
        pub = Path(choice).expanduser()
    if not ui.dry_run and not pub.exists():
        print(f"  skipped: {pub} not found")
        return
    settings = {"gpg.format": "ssh", "user.signingkey": str(pub), "commit.gpgsign": "true", "tag.gpgsign": "true"}
    for key, value in settings.items():
        print(f"  git config --local {key} {value}")
        if not ui.dry_run:
            git("config", "--local", key, value)
    print("  Commits also need a sign-off: use `git commit -s`.")
    if shutil.which("gh") and ui.confirm("Add this key to your GitHub account as a *signing* key with gh?"):
        if not ui.dry_run:
            r = run(["gh", "ssh-key", "add", str(pub), "--type", "signing", "--title", "commit signing"], check=False)
            print("  " + (r.stdout or r.stderr).strip())
    else:
        print("  Add it on GitHub: Settings -> SSH and GPG keys -> New SSH key -> Key type: Signing Key.")


# --- GitHub steps -------------------------------------------------------------

def require_gh(slug: str | None) -> str:
    if not shutil.which("gh"):
        sys.exit("gh (GitHub CLI) is not installed: https://cli.github.com/")
    if run(["gh", "auth", "status"], check=False).returncode != 0:
        sys.exit("gh is not authenticated: run `gh auth login` first.")
    if not slug:
        sys.exit("Could not read owner/repo from the origin remote.")
    return slug


def gh_names(slug: str, kind: str) -> set[str]:
    cmd = ["gh", kind, "list", "-R", slug, "--json", "name", "--jq", ".[].name"]
    r = run(cmd, check=False)
    return set(r.stdout.split()) if r.returncode == 0 else set()


def step_gh_vars(ui: Ui) -> None:
    slug = require_gh(origin_slug())
    heading(f"Actions secrets and variables for {slug}")
    print("  Blank input keeps the current value (or leaves it unset).")
    existing = {"secret": gh_names(slug, "secret"), "variable": gh_names(slug, "variable")}
    for name, kind, required, help_text in GH_SETTINGS:
        state = "set" if name in existing[kind] else ("MISSING" if required else "not set")
        print(f"\n  {name} ({kind}, {'required' if required else 'optional'}, {state})")
        print(f"    {help_text}")
        if ui.yes:
            continue
        prompt = f"    value for {name}: "
        # getpass keeps secrets off the screen; stdin keeps them out of argv
        value = getpass.getpass(prompt) if kind == "secret" else input(prompt).strip()
        if not value:
            continue
        if ui.dry_run:
            print(f"    would set {name}")
            continue
        r = run(["gh", kind, "set", name, "-R", slug], check=False, input_text=value)
        print("    " + ("saved" if r.returncode == 0 else f"failed: {r.stderr.strip()}"))


def step_governance(ui: Ui) -> None:
    slug = require_gh(origin_slug())
    heading(f"Repository governance for {slug}")
    print("  Applies .github/rulesets/main.json and the merge, Actions and security settings.")
    if ui.dry_run or not ui.confirm("Run scripts/apply-governance.sh now?"):
        return
    subprocess.run(["bash", "scripts/apply-governance.sh", slug], check=False)


def step_workflow_check(_: Ui) -> int:
    heading("Configuration check")
    problems = 0

    def report(ok: bool | None, text: str) -> None:
        nonlocal problems
        mark = {True: "ok  ", False: "FAIL", None: "warn"}[ok]
        problems += ok is False
        print(f"  [{mark}] {text}")

    slug = origin_slug()
    report(bool(slug), f"origin remote: {slug or 'not a GitHub URL'}")

    leftovers = sorted({str(p) for p in tracked_text_files()
                        for s in (TEMPLATE_SLUG, PLACEHOLDER_SLUG, '"package-name": "REPO"')
                        if s in p.read_text(encoding="utf-8")})
    if slug == TEMPLATE_SLUG:
        report(None, "origin is the template itself; owner/repo references not checked")
    else:
        report(not leftovers, "owner/repo references " +
               (f"left in: {', '.join(leftovers)} (run --rename)" if leftovers else "updated"))

    generated = [p for p in TEMPLATE_FILES if Path(p).exists()]
    report(None if generated else True,
           f"template results present: {', '.join(generated)} (run --clean)" if generated else "no template results left")

    manifest = Path(".release-please-manifest.json")
    version = json.loads(manifest.read_text()).get(".", "") if manifest.exists() else ""
    report(bool(SEMVER.match(version)), f".release-please-manifest.json version: {version or 'missing'}")

    contact_set = CONTACT_PLACEHOLDER not in Path("CODE_OF_CONDUCT.md").read_text()
    report(contact_set or None, "Code of Conduct contact " + ("set" if contact_set else "not set (run --contact)"))

    signing = {k: run(["git", "config", "--get", k], check=False).stdout.strip()
               for k in ("commit.gpgsign", "user.signingkey", "gpg.format")}
    report(signing["commit.gpgsign"] == "true" and bool(signing["user.signingkey"]),
           "commit signing configured" if signing["user.signingkey"] else "commit signing not configured (run --signing)")
    hooks = run(["git", "config", "--get", "core.hooksPath"], check=False).stdout.strip()
    report(hooks == ".githooks" or None, "git hooks " + ("enabled" if hooks == ".githooks" else "not enabled (enter `nix develop`)"))

    if not (shutil.which("gh") and run(["gh", "auth", "status"], check=False).returncode == 0 and slug):
        report(None, "gh not available or not authenticated: GitHub checks skipped")
        return problems
    if run(["gh", "api", f"repos/{slug}", "--silent"], check=False).returncode != 0:
        report(False, f"github.com/{slug} not reachable with this gh login: GitHub checks skipped")
        return problems

    secrets, variables = gh_names(slug, "secret"), gh_names(slug, "variable")
    for name, kind, required, _ in GH_SETTINGS:
        present = name in (secrets if kind == "secret" else variables)
        report(True if present else (False if required else None),
               f"{kind} {name} " + ("set" if present else "not set" + ("" if required else " (optional)")))

    sonar_text = Path(".sast/sonar-project.properties").read_text()
    if "SONARQUBE_TOKEN" in secrets:
        filled = not any(v in sonar_text for v in SONAR_PLACEHOLDERS.values())
        report(filled, "SonarQube keys " + ("set" if filled else "still placeholders (run --sonar)"))

    r = run(["gh", "api", f"repos/{slug}/rules/branches/main", "--jq",
             '.[] | select(.type=="required_status_checks") | .parameters.required_status_checks[].context'], check=False)
    checks = r.stdout.split()
    report("ci-required" in checks, "main requires ci-required" if checks else "no branch ruleset on main (run --governance)")

    r = run(["gh", "api", f"repos/{slug}/actions/permissions/workflow", "--jq", ".default_workflow_permissions"], check=False)
    perm = r.stdout.strip() if r.returncode == 0 else ""
    report(perm == "read", f"default GITHUB_TOKEN permission: {perm or 'unknown'}")

    r = run(["gh", "api", f"repos/{slug}", "--jq", "[.allow_squash_merge, .allow_merge_commit, .allow_rebase_merge] | @tsv"], check=False)
    report(r.stdout.split() == ["true", "false", "false"], "squash-only merges" if r.stdout.split() == ["true", "false", "false"]
           else "merge settings differ from squash-only (run --governance)")
    return problems


# --- entry point --------------------------------------------------------------

LOCAL_STEPS = [("clean", step_clean), ("rename", step_rename), ("version", step_version),
               ("contact", step_contact), ("sonar", step_sonar), ("signing", step_signing)]


def main() -> int:
    parser = argparse.ArgumentParser(
        prog="adapt.py",
        description=__doc__.split("\n\n", 1)[0],
        formatter_class=argparse.RawDescriptionHelpFormatter,
        epilog="""\
examples:
  ./adapt.py                 walk through every local step
  ./adapt.py --rename --yes  only rewrite owner/repo from origin, no prompts
  ./adapt.py --gh-vars       set Actions secrets and variables with gh
  ./adapt.py --governance    apply the branch ruleset and repo settings
  ./adapt.py --workflow      check the result; exit status 1 on a failure

Typical order after "Use this template": ./adapt.py, commit, push,
./adapt.py --gh-vars --governance, then ./adapt.py --workflow.
See README-ADAPT.md for what each step changes.""",
    )
    steps = parser.add_argument_group("local steps (default: all of them)")
    steps.add_argument("--clean", action="store_true", help="delete the template's generated results")
    steps.add_argument("--rename", action="store_true", help="replace template owner/repo references with origin's")
    steps.add_argument("--version", action="store_true", help="set the current version in .release-please-manifest.json")
    steps.add_argument("--contact", action="store_true", help="set the Code of Conduct contact")
    steps.add_argument("--sonar", action="store_true", help="set the SonarQube Cloud organisation and project keys")
    steps.add_argument("--signing", action="store_true", help="configure SSH commit signing in this clone only")
    github = parser.add_argument_group("GitHub (needs an authenticated gh with admin rights)")
    github.add_argument("--gh-vars", action="store_true", help="prompt for each Actions secret and variable")
    github.add_argument("--governance", action="store_true", help="run scripts/apply-governance.sh")
    github.add_argument("--workflow", action="store_true", help="check the whole configuration; exit 1 on errors")
    parser.add_argument("-y", "--yes", action="store_true", help="accept every default, never prompt")
    parser.add_argument("-n", "--dry-run", action="store_true", help="print what would change, change nothing")
    args = parser.parse_args()

    root = Path(git("rev-parse", "--show-toplevel"))
    os.chdir(root)
    ui = Ui(args.yes, args.dry_run)

    selected = [fn for name, fn in LOCAL_STEPS if getattr(args, name)]
    remote_steps = args.gh_vars or args.governance or args.workflow
    if not selected and not remote_steps:
        selected = [fn for _, fn in LOCAL_STEPS]
    try:
        for fn in selected:
            fn(ui)
        if args.gh_vars:
            step_gh_vars(ui)
        if args.governance:
            step_governance(ui)
        if args.workflow:
            return 1 if step_workflow_check(ui) else 0
    except (KeyboardInterrupt, EOFError):
        print("\naborted")
        return 130
    if selected and not args.dry_run:
        print("\nDone. Review with `git diff`, then commit (git commit -s).")
    return 0


if __name__ == "__main__":
    sys.exit(main())
